BEGIN;

-- 以video表取代video_metadata
-- 只保留站点用到的字段，原始yt-dlp元数据不再随数据库分发
DROP TABLE IF EXISTS video_metadata;

-- 贴吧短视频与外部视频（优酷、腾讯视频）统一，CDN上均为 videos/full/{id}.mp4
-- 只收录CDN上存在mp4的视频，有记录即可播放，无记录即为失效视频
CREATE TABLE IF NOT EXISTS video (
  id text PRIMARY KEY NOT NULL,  -- 贴吧短视频为URL中的video参数，外部视频为优酷/腾讯视频ID
  width integer NOT NULL,        -- CDN上mp4的实际尺寸
  height integer NOT NULL,
  cover text,                    -- 封面在CDN上的路径（images/full/{hash}.jpg 或 videos/cover/{id}.jpg），无封面为NULL
  cover_width integer,
  cover_height integer,
  title text,                    -- 以下仅外部视频，取自yt-dlp元数据
  uploader text,
  uploader_url text
) WITHOUT ROWID;

-- 贴吧短视频的封面来自原链接的thumbnail参数，以下三个例外：
--   1623856_bcd631dd...与93593959_55ecf5f5...：原链接thumbnail为空，封面于2026-11经贴吧客户端API（aiotieba get_posts）取得
--   460_9192a321...：先后两次发布，thumbnail分别为c8fcc3ce...与0cf431ad...，两张封面内容完全相同，取较早的一张

-- 补充管理日志media中的图片
-- 来自un_post.media，此前从未使用过

COMMIT;
ANALYZE;
VACUUM;
